import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { MemoryStore } from "../src/store.ts";

describe("MemoryStore series cap", () => {
  it("admits distinct series up to the cap", () => {
    const store = new MemoryStore(10, 2);
    assert.equal(store.put({ series: "a", value: 1, at: 0 }), true);
    assert.equal(store.put({ series: "b", value: 1, at: 0 }), true);
    assert.deepEqual(store.series(), ["a", "b"]);
  });

  it("refuses a brand-new series once the cap is reached, without displacing an existing one", () => {
    const store = new MemoryStore(10, 2);
    store.put({ series: "a", value: 1, at: 0 });
    store.put({ series: "b", value: 1, at: 0 });

    const admitted = store.put({ series: "c", value: 1, at: 0 });

    assert.equal(admitted, false);
    assert.deepEqual(store.series(), ["a", "b"]);
    assert.equal(store.size(), 2);
  });

  it("keeps accepting samples for already-known series once the cap is hit", () => {
    const store = new MemoryStore(10, 2);
    store.put({ series: "a", value: 1, at: 0 });
    store.put({ series: "b", value: 1, at: 0 });
    store.put({ series: "c", value: 1, at: 0 }); // refused — cap already full

    assert.equal(store.put({ series: "a", value: 2, at: 1_000 }), true);
    assert.equal(store.range("a", 0, 2_000).length, 2);
  });

  it("rejects a non-positive-integer maxSeries", () => {
    assert.throws(() => new MemoryStore(10, 0), RangeError);
    assert.throws(() => new MemoryStore(10, 1.5), RangeError);
  });
});

