    store.put({ series: "a", value: 1, at: 0 });
    store.put({ series: "b", value: 1, at: 0 });
    assert.throws(() => store.put({ series: "c", value: 1, at: 0 }));

    store.put({ series: "a", value: 2, at: 1_000 });
    assert.equal(store.range("a", 0, 2_000).length, 2);
  });

  it("names the refused series and the cap on the thrown error", () => {
    const store = new MemoryStore(10, 1);
    store.put({ series: "a", value: 1, at: 0 });

    try {
      store.put({ series: "b", value: 1, at: 0 });
      assert.fail("expected SeriesCapError");
    } catch (error) {
      assert.ok(error instanceof SeriesCapError);
      assert.equal(error.series, "b");
      assert.equal(error.maxSeries, 1);
    }
  });

  it("rejects a non-positive-integer maxSeries", () => {
    assert.throws(() => new MemoryStore(10, 0), RangeError);
    assert.throws(() => new MemoryStore(10, 1.5), RangeError);
  });
});

