import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { FixedClock } from "../src/clock.ts";
import { DEFAULT_CONFIG } from "../src/config.ts";
import { createRouter } from "../src/router.ts";
import { MemoryStore } from "../src/store.ts";

function router(maxSeries: number) {
  const store = new MemoryStore(DEFAULT_CONFIG.maxSamples, maxSeries);
  const clock = new FixedClock(1_000);
  return createRouter(store, { ...DEFAULT_CONFIG, maxSeries }, clock);
}

describe("Router ingest — series cap", () => {
  it("accepts samples for distinct series up to the cap", () => {
    const reply = router(2).dispatch("POST", "/samples", "a 1\nb 2");
    assert.equal(reply.status, 202);
    assert.equal(reply.body, "accepted 2");
  });

  it("responds distinctly from a malformed payload once the cap is full", () => {
    const r = router(1);
    r.dispatch("POST", "/samples", "a 1");

    const capped = r.dispatch("POST", "/samples", "b 2");
    assert.equal(capped.status, 507);
    assert.match(capped.body, /series cap reached/);

    const malformed = r.dispatch("POST", "/samples", "a not-a-number");
    assert.equal(malformed.status, 400);
    assert.notEqual(malformed.status, capped.status);
  });

  it("keeps accepting samples for an already-known series once the cap is full", () => {
    const r = router(1);
    r.dispatch("POST", "/samples", "a 1");
    r.dispatch("POST", "/samples", "b 2"); // refused — cap already full

    const reply = r.dispatch("POST", "/samples", "a 2");
    assert.equal(reply.status, 202);
    assert.equal(reply.body, "accepted 1");
  });
});

